css:
@page {
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format,
.print-format-container {
  margin: 0 !important;
  padding: 0 !important;
}

.menu-print {
  width: 100%;
  font-family: Arial, sans-serif;
  color: #000;
}

.period-page {
  width: 100%;
  min-height: 100vh;
  padding: 10mm;
  box-sizing: border-box;
  page-break-after: always;
}

.period-page:last-child {
  page-break-after: auto;
}

.menu-page-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 6px;
  text-align: center;
}

.menu-page-subtitle {
  font-size: 12px;
  margin-bottom: 8px;
  color: #444;
  text-align: center;
}

.meal-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse !important;
  margin-bottom: 0 !important;
}

.meal-table th,
.meal-table td {
  border: 1px solid #cfcfcf !important;
  padding: 0 !important;
  margin: 0 !important;
  vertical-align: middle !important;
}

.meal-table thead th {
  text-align: center !important;
  vertical-align: middle !important;
}

.period-header {
  background-color: #eeeeee !important;
  height: 40px;
  font-size: 20px;
  font-weight: 700;
  text-align: center !important;
}

.meal-header {
  background-color: #eeeeee !important;
  height: 34px;
  font-size: 15px;
  font-weight: 700;
  text-align: center !important;
}

.section-cell {
  background-color: #cfe9ec !important;
  width: 16%;
  font-size: 14px;
  font-weight: 700;
  text-align: center !important;
}

.meal-cell {
  background: transparent !important;
  background-color: transparent !important;
  width: 21%;
  min-height: 60px;
  text-align: center !important;
}

.item-block {
  display: block;
  margin: 0;
  padding: 4px 3px;
  line-height: 1.35;
  text-align: center;
}

.item-block + .item-block {
  margin-top: 4px;
}

.item-name {
  display: block;
  font-size: 14px;
  font-weight: 400;
  margin: 0;
  padding: 0;
  text-align: center;
}

.item-name-arabic {
  display: block;
  font-size: 12px;
  direction: rtl;
  text-align: center;
  margin: 0;
  padding: 0;
}

@media print {
  .period-page {
    page-break-after: always;
  }

  .period-page:last-child {
    page-break-after: auto;
  }

  .meal-cell {
    background: transparent !important;
    background-color: transparent !important;
  }
}
